package io.colorsand.ui.hud

import androidx.compose.foundation.Canvas
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.geometry.CornerRadius
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.rotate
import io.colorsand.core.Arena

/** The colors an arena is announced in, on badges and map banners: a [light] and a [deep] tone. */
class ArenaColors(val light: Color, val deep: Color)

fun arenaColors(arena: Arena): ArenaColors = when (arena) {
    Arena.PLAYGROUND -> ArenaColors(Color(0xFF8BD66B), Color(0xFF3E9A45))
    Arena.BEACH -> ArenaColors(Color(0xFF5FD3DC), Color(0xFF1B8FB0))
    Arena.DESERT -> ArenaColors(Color(0xFFFFB859), Color(0xFFD06A2C))
}

/**
 * A round badge for [arena]: a disc in the arena's colors with a white rim and a little emblem on it,
 * a bucket and spade for the Playground, a shell for the Beach, a cactus under the sun for the Desert.
 */
@Composable
fun ArenaBadge(arena: Arena, modifier: Modifier = Modifier) {
    val colors = arenaColors(arena)
    Canvas(modifier) {
        val r = size.minDimension / 2
        val c = center
        drawCircle(Color.Black.copy(alpha = 0.2f), r, c + Offset(0f, r * 0.08f))
        drawCircle(Color.White, r * 0.98f, c)
        drawCircle(Brush.verticalGradient(listOf(colors.light, colors.deep), c.y - r, c.y + r), r * 0.86f, c)
        // A soft shine on the upper half of the disc.
        drawOval(
            Color.White.copy(alpha = 0.28f),
            Offset(c.x - r * 0.6f, c.y - r * 0.78f),
            Size(r * 1.2f, r * 0.62f),
        )
        drawEmblem(arena, c, r * 0.86f / 10f)
    }
}

/** Draws [arena]'s emblem around [c], about 16 [u] across. */
fun DrawScope.drawEmblem(arena: Arena, c: Offset, u: Float) {
    when (arena) {
        Arena.PLAYGROUND -> bucketAndSpade(c, u)
        Arena.BEACH -> shell(c, u)
        Arena.DESERT -> cactusAndSun(c, u)
    }
}

/** A red bucket with a handle and a yellow spade leaning in it; [u] is a tenth of the disc's radius. */
private fun DrawScope.bucketAndSpade(c: Offset, u: Float) {
    val outline = Color(0xFF6B2A1A)
    // Spade first, so the bucket covers its lower handle.
    rotate(28f, c) {
        drawLine(Color(0xFFFFE07A), Offset(c.x + 1.5f * u, c.y - 7f * u), Offset(c.x + 1.5f * u, c.y + 1f * u), 1.4f * u, StrokeCap.Round)
        val blade = Path().apply {
            moveTo(c.x - 1f * u, c.y - 7.5f * u)
            lineTo(c.x + 4f * u, c.y - 7.5f * u)
            lineTo(c.x + 4f * u, c.y - 4f * u)
            quadraticBezierTo(c.x + 1.5f * u, c.y - 1.5f * u, c.x - 1f * u, c.y - 4f * u)
            close()
        }
        drawPath(blade, Color(0xFFFFC93C))
    }
    val bucket = Path().apply {
        moveTo(c.x - 5f * u, c.y - 2f * u)
        lineTo(c.x + 5f * u, c.y - 2f * u)
        lineTo(c.x + 3.8f * u, c.y + 6f * u)
        lineTo(c.x - 3.8f * u, c.y + 6f * u)
        close()
    }
    drawArc(
        outline, 180f, 180f, false,
        Offset(c.x - 4.2f * u, c.y - 6.5f * u), Size(8.4f * u, 9f * u),
        style = Stroke(0.8f * u),
    )
    drawPath(bucket, Color(0xFFF2564B))
    drawRoundRect(Color(0xFFFF8A7F), Offset(c.x - 5.4f * u, c.y - 2.8f * u), Size(10.8f * u, 1.8f * u), CornerRadius(0.9f * u))
    drawRect(Color.White.copy(alpha = 0.35f), Offset(c.x - 3f * u, c.y - 0.5f * u), Size(1f * u, 5f * u))
}

/** A peach scallop shell with ribs fanning from its hinge. */
private fun DrawScope.shell(c: Offset, u: Float) {
    val hinge = Offset(c.x, c.y + 6f * u)
    val fan = Path().apply {
        moveTo(hinge.x - 1.6f * u, hinge.y)
        lineTo(c.x - 6.5f * u, c.y - 1f * u)
        // A scalloped rim along the top.
        val bumps = 5
        for (i in 0 until bumps) {
            val x0 = -6.5f + 13f * i / bumps
            val x1 = -6.5f + 13f * (i + 1) / bumps
            val y0 = rimY(x0)
            val y1 = rimY(x1)
            quadraticBezierTo(c.x + (x0 + x1) / 2 * u, c.y + (minOf(y0, y1) - 1.6f) * u, c.x + x1 * u, c.y + y1 * u)
        }
        lineTo(hinge.x + 1.6f * u, hinge.y)
        close()
    }
    drawPath(fan, Brush.verticalGradient(listOf(Color(0xFFFFE3CC), Color(0xFFFF9E7A)), c.y - 7f * u, hinge.y))
    for (i in 0..4) {
        val x = -5.2f + 10.4f * i / 4
        drawLine(Color(0xFFE0704E), hinge, Offset(c.x + x * u, c.y + (rimY(x) + 1.2f) * u), 0.6f * u, StrokeCap.Round)
    }
    drawRoundRect(Color(0xFFFF9E7A), Offset(hinge.x - 2.6f * u, hinge.y - 0.6f * u), Size(5.2f * u, 2.2f * u), CornerRadius(0.8f * u))
}

/** The shell's rim height at [x] across it, both in tenths of the radius: highest in the middle. */
private fun rimY(x: Float): Float = -5.5f + 0.08f * x * x

/** A green saguaro in front of a big low sun. */
private fun DrawScope.cactusAndSun(c: Offset, u: Float) {
    drawCircle(Color(0xFFFFF0A8), 4.2f * u, Offset(c.x + 2.8f * u, c.y - 2.6f * u))
    drawCircle(Color.White.copy(alpha = 0.35f), 5.4f * u, Offset(c.x + 2.8f * u, c.y - 2.6f * u))
    val green = Color(0xFF3F9A4A)
    val w = 2.6f * u
    drawLine(green, Offset(c.x - 1f * u, c.y + 7f * u), Offset(c.x - 1f * u, c.y - 5.5f * u), w, StrokeCap.Round)
    // The arms: out sideways, then up.
    val arms = Path().apply {
        moveTo(c.x - 1f * u, c.y + 1.5f * u)
        lineTo(c.x - 4.6f * u, c.y + 1.5f * u)
        lineTo(c.x - 4.6f * u, c.y - 2.6f * u)
        moveTo(c.x - 1f * u, c.y - 0.5f * u)
        lineTo(c.x + 2.6f * u, c.y - 0.5f * u)
        lineTo(c.x + 2.6f * u, c.y - 3.8f * u)
    }
    drawPath(arms, green, style = Stroke(1.9f * u, cap = StrokeCap.Round, join = StrokeJoin.Round))
    drawLine(Color.White.copy(alpha = 0.3f), Offset(c.x - 1.5f * u, c.y + 5f * u), Offset(c.x - 1.5f * u, c.y - 4.5f * u), 0.6f * u, StrokeCap.Round)
    drawOval(Color(0xFFB8642E), Offset(c.x - 6f * u, c.y + 6f * u), Size(12f * u, 2.4f * u))
}
