/**
 * The pour animation: the paw that holds the source tube (see [PawHold]) carries it over the target and tilts it,
 * the sand runs across in a stream, and the paw puts the tube back and leaves to the side. It only draws the step
 * from [PourEvent.before] to the current board; the game itself has already made the move.
 */
@Stable
class PourAnimation(private val game: GameController) {
    private val clock = Animatable(1f)

    // Pour ids start at 1. The pour that has started animating and the last one that ended.
    private var startedId by mutableStateOf(0)
    private var finishedId by mutableStateOf(0)

    /**
     * The pour being animated, or null when the board is at rest. It follows [GameController.lastPour] right
     * away, so not even one frame shows the board after the pour before the animation starts.
     */
    val pour: PourEvent? get() = game.lastPour?.takeIf { it.id != finishedId }
    val isRunning: Boolean get() = pour != null

    /** How far the animation is, from 0 to 1. Read it while drawing, so frames don't recompose. */
    internal val progress: Float get() = if (pour?.id == startedId) clock.value else 0f

    // Where each tube rests (without its selection lift) and where the board is, in root coordinates.
    private val tubesInRoot = mutableStateMapOf<Int, Rect>()
    private var boardInRoot by mutableStateOf(Offset.Zero)
    internal var boardWidth by mutableStateOf(0f)
        private set
    private var rootWidth by mutableStateOf(0f)

    /** Jumps to the end, so a tap made while sand is still running acts on the finished board. */
    fun finish() {
        game.lastPour?.let { finishedId = maxOf(finishedId, it.id) }
    }

    internal suspend fun play(event: PourEvent) {
        try {
            clock.snapTo(0f)
            startedId = event.id
            clock.animateTo(1f, tween(POUR_MILLIS, easing = LinearEasing))
        } finally {
            // Ids only grow: an older pour cancelled late must not revive a newer one that a tap already finished.
            finishedId = maxOf(finishedId, event.id)
        }
    }

    internal fun placeBoard(coordinates: LayoutCoordinates) {
        boardInRoot = coordinates.positionInRoot()
        boardWidth = coordinates.size.width.toFloat()
        rootWidth = coordinates.findRootCoordinates().size.width.toFloat()
    }

    /** The x of the screen's left (side -1) or right (side 1) edge, relative to the board. */
    internal fun screenEdge(side: Int): Float = if (side < 0) -boardInRoot.x else rootWidth - boardInRoot.x

    internal fun placeTube(index: Int, coordinates: LayoutCoordinates) {
        tubesInRoot[index] = Rect(coordinates.positionInRoot(), coordinates.size.let { Size(it.width.toFloat(), it.height.toFloat()) })
    }

    /** Where tube [index] rests, relative to the board. */
    internal fun tubeBounds(index: Int): Rect? = tubesInRoot[index]?.translate(-boardInRoot)
}

@Composable
fun rememberPourAnimation(game: GameController): PourAnimation = remember(game) { PourAnimation(game) }

internal const val POUR_MILLIS = 1300

// The timeline, as fractions of the whole animation. The paw already holds the tube when it starts.
internal const val CATCH_END = 0.1f // at the latest, a paw that hadn't got hold of the tube yet (a quick second tap) has it
internal const val LIFT_END = 0.32f // the tube is tilted over the target
internal const val POUR_END = 0.68f // the last grain has landed
internal const val BACK_END = 0.9f // the tube is back in its place, and the paw lets go and leaves to the side

/** How far [p] is from [start] to [end], clamped to 0..1. */
internal fun phase(p: Float, start: Float, end: Float): Float = ((p - start) / (end - start)).coerceIn(0f, 1f)

private fun smooth(x: Float): Float = x * x * (3 - 2 * x)

/** The share of the poured sand that has left the source at animation progress [p]. */
internal fun drained(p: Float): Float = smooth(phase(phase(p, LIFT_END, POUR_END), 0f, 0.85f))

/**
 * The share of the poured sand that has landed in the target at progress [p]. It trails [drained] by the time
 * a grain takes to fall, so the stream is as long as the gap between them.
 */
internal fun landed(p: Float): Float = smooth(phase(phase(p, LIFT_END, POUR_END), 0.15f, 1f))

/**
 * The lifted tube's position: [pivot] is the middle of its mouth, [angle] its tilt in degrees, clockwise, and
 * [scale] its size relative to the tube at rest.
 */
internal class Pose(val pivot: Offset, val angle: Float, val scale: Float = 1f)

internal fun Offset.rotated(degrees: Float): Offset {
    val r = degrees * PI.toFloat() / 180f
    return Offset(x * cos(r) - y * sin(r), x * sin(r) + y * cos(r))
}

private fun lerp(a: Offset, b: Offset, f: Float) = a + (b - a) * f

/**
 * The geometry of one pour, from tube [src] to tube [dst] (bounds relative to the board). [grabbed] is how far
 * the paw had got with the source tube when the pour began (see [PawHold]), normally all the way.
 */
internal class PourPath(val src: Rect, val dst: Rect, private val boardWidth: Float, private val grabbed: Float = 1f) {
    val w = src.width

    /** The side the paw holds the tube from. */
    val side = pawSide(src, boardWidth)

    /** Where the stream leaves the lip while pouring: a little above the middle of the target's mouth. */
    val spout = Offset(dst.center.x, dst.top - w * 0.3f)

    // Tilt towards the target, so the tube's body stays on the source's side. Straight above or below
    // (pours across rows), lean the body towards the middle of the board. If the body would stick out of
    // the board on that side, tilt the other way. If it fits neither way, tilt to the roomier side and shrink
    // the tube to [fitScale] while it is over the target, so it stays on the board.
    private val reach = src.height * sin(70f * PI.toFloat() / 180f) + w * 0.5f
    private fun room(d: Float) = if (d > 0) spout.x else boardWidth - spout.x
    val dir = run {
        val preferred = when {
            dst.center.x > src.center.x + 1f -> 1f
            dst.center.x < src.center.x - 1f -> -1f
            dst.center.x >= boardWidth / 2 -> 1f
            else -> -1f
        }
        fun fits(d: Float) = room(d) >= reach
        when {
            fits(preferred) -> preferred
            fits(-preferred) -> -preferred
            room(-preferred) > room(preferred) -> -preferred
            else -> preferred
        }
    }

    /** How small the tube must get over the target to stay on the board; 1 when it fits as it is. */
    val fitScale = (room(dir) / reach).coerceIn(0.4f, 1f)

    private fun scaleAt(f: Float) = 1f + (fitScale - 1f) * f

    /** The lip the sand runs over, relative to the pivot of an upright tube. */
    val lip = Offset(dir * w * 0.42f, w * 0.03f)

    val rest = Offset(src.center.x, src.top)
    val lifted = rest + Offset(0f, -w * HOLD_LIFT * holdLift(grabbed)) // the tube starts held up by the paw

    // It tips further as it empties.
    fun tilt(s: Float) = dir * (52f + 18f * FastOutSlowInEasing.transform(s))

    fun pourPivot(angle: Float) = spout - (lip * fitScale).rotated(angle)

    /**
     * When the paw has hold of the tube: at once if it already had, else after it has come the rest of the way.
     * The tube waits for it, so it never moves on its own.
     */
    val caught = CATCH_END * holdAway(grabbed)

    private fun catching(p: Float) = if (caught <= 0f) 1f else phase(p, 0f, caught)

    fun pose(p: Float): Pose = when {
        p < LIFT_END -> {
            val f = FastOutSlowInEasing.transform(phase(p, caught, LIFT_END))
            val angle = tilt(0f) * FastOutSlowInEasing.transform(phase(p, caught + 0.08f, LIFT_END))
            Pose(lerp(lifted, pourPivot(angle), f) + arc(f), angle, scaleAt(f))
        }
        p < POUR_END -> tilt(phase(p, LIFT_END, POUR_END)).let { Pose(pourPivot(it), it, fitScale) }
        p < BACK_END -> {
            val f = FastOutSlowInEasing.transform(phase(p, POUR_END, BACK_END))
            val angle = tilt(1f) * (1 - FastOutSlowInEasing.transform(phase(p, POUR_END, BACK_END - 0.04f)))
            Pose(lerp(pourPivot(tilt(1f)), rest, f) + arc(f), angle, scaleAt(1 - f))
        }
        else -> Pose(rest, 0f)
    }

    // A gentle hop on the way over and back.
    private fun arc(f: Float) = Offset(0f, -w * 0.5f * sin(PI.toFloat() * f))

    /** Where the paw is at progress [p] for the tube at [pose]: on the tube, but coming in or leaving to the side. */
    fun grip(p: Float, pose: Pose) =
        gripPoint(pose.pivot, w, side, pose.angle, pose.scale) + Offset(side * PAW_TRAVEL * w * pawAway(p), 0f)

    /** How much of [PAW_TRAVEL] the paw is away from the tube at progress [p]. */
    fun pawAway(p: Float): Float =
        holdAway(grabbed) * (1 - catching(p)) + FastOutSlowInEasing.transform(phase(p, BACK_END, 1f))

    fun pawAlpha(p: Float): Float =
        (holdAlpha(grabbed) + (1 - holdAlpha(grabbed)) * catching(p)) * (1 - phase(p, BACK_END + 0.04f, 1f))
}

/**
 * Draws the running pour above the board: the lifted tube, the stream and the paw. [board] is the board after the
 * pour; [onTap] gets taps on the lifted tube, which stands in for the source tube.
 */
@Composable
internal fun BoxScope.PourOverlay(pours: PourAnimation, board: Board, tubeWidth: Dp, grabbed: Float, onTap: (Int) -> Unit) {
    val pour = pours.pour ?: return
    val from = pour.move.from
    val to = pour.move.to
    val src = pours.tubeBounds(from) ?: return
    val dst = pours.tubeBounds(to) ?: return
    val palette = LocalPalette.current
    val target = pour.before.tubes[to]
    val sand = palette.sand(pour.color)
    val kind = LocalPawKind.current
    val look = pawLook(kind, palette)

    val path = PourPath(src, dst, pours.boardWidth, grabbed)
    val rise = armRise(src, board.tubes.indices.mapNotNull(pours::tubeBounds))
    val edge = pours.screenEdge(path.side)
    val drop = pawDrop(kind, path.side, rise)

    // Drawing reads the progress only in the draw and layer phases, so the frames don't recompose anything.
    Box(Modifier.matchParentSize()) {
        Canvas(Modifier.matchParentSize()) {
            val p = pours.progress
            val pose = path.pose(p)
            drawStream(path, pose, p, target.size + pour.move.amount * landed(p), target.capacity, sand)
        }
        TubeView(
            tube = board.tubes[from],
            highlight = TubeHighlight.NONE,
            width = tubeWidth,
            onTap = { onTap(from) },
            pouring = PouringSand(pour.color) { pour.move.amount * (1 - drained(pours.progress)) },
            modifier = Modifier.graphicsLayer {
                val pose = path.pose(pours.progress)
                translationX = pose.pivot.x - src.width / 2
                translationY = pose.pivot.y
                rotationZ = pose.angle
                scaleX = pose.scale
                scaleY = scaleX
                transformOrigin = TransformOrigin(0.5f, 0f)
            },
        )
        Canvas(Modifier.matchParentSize()) {
            val p = pours.progress
            val pose = path.pose(p)
            val grip = path.grip(p, pose)
            val center = pawCenter(grip, path.w, drop, pose.angle, pose.scale)
            withAlpha(path.pawAlpha(p)) {
                drawForearm(kind, look, grip, path.w, armWidth(kind, rise) * path.w * pose.scale, path.side, rise, edge)
                drawPaw(kind, look, center, path.w * pose.scale, pawRotation(path.side, pose.angle))
            }
        }
    }
}

/** The stream of sand from the lifted tube's lip down to the sand in the target. */
private fun DrawScope.drawStream(path: PourPath, pose: Pose, p: Float, targetUnits: Float, capacity: Int, sand: Color) {
    val s = phase(p, LIFT_END, POUR_END)
    if (s <= 0f || s >= 1f) return
    val w = path.w
    val start = pose.pivot + (path.lip * pose.scale).rotated(pose.angle)
    val surface = path.dst.bottom - sandLevel(w, path.dst.height, capacity, targetUnits)
    val fall = surface - start.y
    if (fall <= 0f) return
    val head = start.y + fall * phase(s, 0f, 0.15f)
    val tail = start.y + fall * phase(s, 0.85f, 1f)
    val width = w * 0.14f
    drawRoundRect(sand, topLeft = Offset(start.x - width / 2, tail), size = Size(width, head - tail), cornerRadius = CornerRadius(width / 2))
    // Grains tumbling down the stream.
    var state = 12345
    fun next(): Float {
        state = state * 1103515245 + 12345
        return ((state ushr 8) and 0xFFFF) / 65535f
    }
    repeat(28) {
        val shade = if (next() > 0.5f) Color.White.copy(alpha = 0.25f) else Color.Black.copy(alpha = 0.2f)
        val y = start.y + ((next() + s * 5f) % 1f) * fall
        val side = w * 0.03f * (0.6f + next())
        val x = start.x + (next() - 0.5f) * (width - side)
        if (y in tail..head - side) drawRect(shade, topLeft = Offset(x, y), size = Size(side, side))
    }
    // A little puff where it lands.
    if (head >= surface - 0.5f && tail < surface) {
        drawOval(sand, topLeft = Offset(start.x - w * 0.22f, surface - w * 0.07f), size = Size(w * 0.44f, w * 0.14f))
    }
}
