package io.colorsand.ui.arena

import androidx.compose.ui.graphics.Color
import io.colorsand.ui.Palette
import io.colorsand.ui.Palettes

/**
 * How a color scheme grades the arena art. The scenery keeps its own colors; the grade only shifts them, so
 * every scheme looks like the same place in a different light:
 * Classic is full vivid daylight, Soft is calmer and a little grayer, Pastel is a light, airy wash,
 * and a custom scheme tints the scene toward its own sky colors.
 *
 * Scenes run every key color through the grade once, when they build their brushes, so it costs nothing per frame.
 */
class SceneGrade private constructor(
    /** 1 keeps the saturation, 0 turns the scene gray. */
    private val saturation: Float,
    /** The color the scene is washed toward, by [washAmount]. */
    private val wash: Color,
    private val washAmount: Float,
    /** A colored filter multiplied over the scene; white leaves it as it is. */
    private val filter: Color,
) {
    /** [color] as this grade shows it. Alpha is kept. */
    operator fun invoke(color: Color): Color {
        val luma = 0.299f * color.red + 0.587f * color.green + 0.114f * color.blue
        fun channel(c: Float, washC: Float, filterC: Float): Float {
            val saturated = luma + (c - luma) * saturation
            return ((saturated + (washC - saturated) * washAmount) * filterC).coerceIn(0f, 1f)
        }
        return Color(
            channel(color.red, wash.red, filter.red),
            channel(color.green, wash.green, filter.green),
            channel(color.blue, wash.blue, filter.blue),
            color.alpha,
        )
    }

    /** The color with ARGB value [argb], graded. */
    operator fun invoke(argb: Long): Color = invoke(Color(argb))

    companion object {
        /** Leaves every color as it is: Classic's vivid daylight. */
        val Vivid = SceneGrade(1f, Color.White, 0f, Color.White)

        /** Calmer: a little less saturated and pulled toward a quiet lavender gray. */
        val Calm = SceneGrade(0.75f, Color(0xFF8F8C9E), 0.1f, Color.White)

        /** Lighter and airier: less saturated and washed toward warm paper white. */
        val Airy = SceneGrade(0.8f, Color(0xFFFFF7EE), 0.36f, Color.White)

        /** The grade for [palette]: one of the above for the built-in schemes, a tint for any other. */
        fun of(palette: Palette): SceneGrade = when (palette.name) {
            Palettes.Classic.name -> Vivid
            Palettes.Soft.name -> Calm
            Palettes.Pastel.name -> Airy
            else -> tinted(palette.backgroundTop, palette.backgroundBottom)
        }

        /**
         * A gentle tint toward the hue of a custom scheme's sky ([top] to [bottom]). Those skies are dark and only
         * faintly colored, so the hue is taken out of them and strengthened, and the scene keeps its daylight.
         */
        fun tinted(top: Color, bottom: Color): SceneGrade {
            val r = (top.red + bottom.red) / 2
            val g = (top.green + bottom.green) / 2
            val b = (top.blue + bottom.blue) / 2
            val max = maxOf(r, g, b, 0.001f)
            val min = minOf(r, g, b)
            // Stretch the faint hue so its weakest channel sits at 1 - TINT, its strongest at 1. A gray sky has no
            // hue to stretch, so the tint fades out as the sky gets grayer.
            val span = (max - min).coerceAtLeast(0.001f)
            val strength = TINT * (span / FULL_HUE).coerceAtMost(1f)
            fun filter(c: Float) = 1f - strength * (max - c) / span
            val hue = Color(filter(r), filter(g), filter(b))
            return SceneGrade(0.9f, hue, 0.08f, hue)
        }

        /** How far a custom tint takes the scene's weakest channel down. */
        private const val TINT = 0.22f

        /** The channel spread at which a sky counts as fully colored. */
        private const val FULL_HUE = 0.04f
    }
}
