package io.colorsand.ui.hud

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathBuilder
import androidx.compose.ui.graphics.vector.path
import androidx.compose.ui.unit.dp

/**
 * The HUD's icons, drawn by hand on a 24x24 grid with thick round strokes so they stay chunky on a game button.
 * They are white; tint them to the button's content color.
 */
object HudIcons {
    val Undo: ImageVector = icon("Undo") {
        line {
            moveTo(8.5f, 4.5f); lineTo(4f, 9f); lineTo(8.5f, 13.5f)
        }
        line {
            moveTo(4.5f, 9f); lineTo(14f, 9f)
            arcToRelative(5.25f, 5.25f, 0f, isMoreThanHalf = false, isPositiveArc = true, dx1 = 0f, dy1 = 10.5f)
            lineTo(9f, 19.5f)
        }
    }

    val Restart: ImageVector = icon("Restart") {
        line {
            moveTo(19.5f, 12f)
            arcToRelative(7.5f, 7.5f, 0f, isMoreThanHalf = true, isPositiveArc = true, dx1 = -2.2f, dy1 = -5.3f)
        }
        line {
            moveTo(17.3f, 2.6f); lineTo(17.3f, 6.7f); lineTo(13.2f, 6.7f)
        }
    }

    val Hint: ImageVector = icon("Hint") {
        // The glass of the bulb, lightly filled so it glows.
        path(
            fill = SolidColor(Color.White),
            fillAlpha = 0.35f,
            stroke = SolidColor(Color.White),
            strokeLineWidth = STROKE,
            strokeLineCap = StrokeCap.Round,
            strokeLineJoin = StrokeJoin.Round,
        ) {
            moveTo(9f, 16f)
            curveTo(9f, 13.8f, 5.8f, 12.6f, 5.8f, 9f)
            arcToRelative(6.2f, 6.2f, 0f, isMoreThanHalf = false, isPositiveArc = true, dx1 = 12.4f, dy1 = 0f)
            curveTo(18.2f, 12.6f, 15f, 13.8f, 15f, 16f)
            close()
        }
        line { moveTo(9.5f, 19.2f); lineTo(14.5f, 19.2f) }
        line { moveTo(10.8f, 22f); lineTo(13.2f, 22f) }
        // A glint on the glass.
        line(width = 1.8f) {
            moveTo(9f, 8.6f)
            arcToRelative(3f, 3f, 0f, isMoreThanHalf = false, isPositiveArc = true, dx1 = 2.6f, dy1 = -2.6f)
        }
    }

    /** A painter's palette, filled; [PaletteDots] says where its paint dabs go. */
    val Palette: ImageVector = icon("Colors") {
        path(fill = SolidColor(Color.White)) {
            moveTo(12f, 2.5f)
            curveTo(6.5f, 2.5f, 2f, 6.6f, 2f, 11.6f)
            curveTo(2f, 16.6f, 6f, 21f, 11f, 21f)
            curveTo(12.9f, 21f, 13.4f, 19.7f, 12.7f, 18.5f)
            curveTo(12f, 17.2f, 12.6f, 15.8f, 14.4f, 15.8f)
            lineTo(16.8f, 15.8f)
            curveTo(19.8f, 15.8f, 22f, 13.8f, 22f, 10.9f)
            curveTo(22f, 6.2f, 17.5f, 2.5f, 12f, 2.5f)
            close()
        }
    }

    /** Centers of the paint dabs on [Palette], as fractions of the icon's size. */
    val PaletteDots = listOf(0.27f to 0.5f, 0.38f to 0.28f, 0.6f to 0.25f, 0.76f to 0.44f)

    val Levels: ImageVector = icon("Levels") {
        line {
            moveTo(3f, 6f); lineTo(9f, 3.5f); lineTo(15f, 6f); lineTo(21f, 3.5f)
            lineTo(21f, 18f); lineTo(15f, 20.5f); lineTo(9f, 18f); lineTo(3f, 20.5f); close()
        }
        line(width = 2f) { moveTo(9f, 3.5f); lineTo(9f, 18f) }
        line(width = 2f) { moveTo(15f, 6f); lineTo(15f, 20.5f) }
    }

    val Close: ImageVector = icon("Close") {
        line { moveTo(6.5f, 6.5f); lineTo(17.5f, 17.5f) }
        line { moveTo(17.5f, 6.5f); lineTo(6.5f, 17.5f) }
    }

    val Lock: ImageVector = icon("Locked") {
        line(width = 2.6f) {
            moveTo(7.5f, 11f); lineTo(7.5f, 8f)
            arcToRelative(4.5f, 4.5f, 0f, isMoreThanHalf = false, isPositiveArc = true, dx1 = 9f, dy1 = 0f)
            lineTo(16.5f, 11f)
        }
        path(fill = SolidColor(Color.White)) {
            moveTo(6f, 10f); lineTo(18f, 10f)
            arcToRelative(1.8f, 1.8f, 0f, isMoreThanHalf = false, isPositiveArc = true, dx1 = 1.8f, dy1 = 1.8f)
            lineTo(19.8f, 19f)
            arcToRelative(2.5f, 2.5f, 0f, isMoreThanHalf = false, isPositiveArc = true, dx1 = -2.5f, dy1 = 2.5f)
            lineTo(6.7f, 21.5f)
            arcToRelative(2.5f, 2.5f, 0f, isMoreThanHalf = false, isPositiveArc = true, dx1 = -2.5f, dy1 = -2.5f)
            lineTo(4.2f, 11.8f)
            arcToRelative(1.8f, 1.8f, 0f, isMoreThanHalf = false, isPositiveArc = true, dx1 = 1.8f, dy1 = -1.8f)
            close()
        }
    }

    private const val STROKE = 2.6f

    private fun icon(name: String, build: ImageVector.Builder.() -> Unit): ImageVector =
        ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f).apply(build).build()

    private fun ImageVector.Builder.line(width: Float = STROKE, build: PathBuilder.() -> Unit) {
        path(
            stroke = SolidColor(Color.White),
            strokeLineWidth = width,
            strokeLineCap = StrokeCap.Round,
            strokeLineJoin = StrokeJoin.Round,
            pathBuilder = build,
        )
    }
}
