/** Height of a section's banner, and of each level's row on the trail below it. */
private val BannerHeight = 76.dp
private val RowHeight = 104.dp
private val NodeSize = 60.dp

/** Width kept for a node with its tag underneath. */
private val NodeSlot = 100.dp

/** The gold of the next level to play. */
private val NextGold = Color(0xFFFFC52E)

/**
 * Full-screen world map for picking a level: one section per arena visit, each with a banner and its ten levels
 * on a winding dotted trail. Solved levels show their best stars, the next one to solve pulses gently, and the
 * next section is shown locked as a peek ahead. Picking an unlocked level opens it and closes the map.
 */
@Composable
fun LevelSelector(game: GameController, onClose: () -> Unit) {
    DismissOnBack(onBack = onClose)
    val palette = LocalPalette.current
    val unlocked = game.unlockedLevel
    val listState = rememberLazyListState()
    val density = LocalDensity.current
    LaunchedEffect(Unit) {
        // Bring the level being played to the middle of the screen.
        val level = game.levelNumber
        listState.scrollToItem(MapLayout.section(level))
        val viewport = listState.layoutInfo.viewportSize.height
        val nodeY = with(density) { (BannerHeight + RowHeight * (Arena.stage(level) - 1) + RowHeight / 2).toPx() }
        listState.scrollBy(nodeY - viewport / 2f)
    }
    val pulse = rememberInfiniteTransition().animateFloat(
        initialValue = 0f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(tween(900, easing = FastOutSlowInEasing), RepeatMode.Reverse),
    )
    Box(
        Modifier
            .fillMaxSize()
            .background(Brush.verticalGradient(listOf(palette.backgroundTop, palette.backgroundBottom)))
            // Swallow taps so nothing underneath reacts.
            .clickable(remember { MutableInteractionSource() }, indication = null) {}
            .windowInsetsPadding(WindowInsets.safeDrawing),
        contentAlignment = Alignment.TopCenter,
    ) {
        WithGameFont { MapScreen(game, unlocked, listState, pulse, onClose) }
    }
}

@Composable
private fun MapScreen(game: GameController, unlocked: Int, listState: LazyListState, pulse: State<Float>, onClose: () -> Unit) {
    val palette = LocalPalette.current
    Column(Modifier.widthIn(max = 520.dp).fillMaxSize().padding(horizontal = 16.dp)) {
        Row(Modifier.fillMaxWidth().padding(top = 16.dp, bottom = 8.dp), verticalAlignment = Alignment.CenterVertically) {
            Text(
                "World Map",
                color = palette.accent,
                fontSize = 26.sp,
                fontWeight = FontWeight.Black,
                style = LocalTextStyle.current.withTitleShadow(palette),
                modifier = Modifier.semantics { heading() },
            )
            Spacer(Modifier.weight(1f))
            StarTotal(game.stars.total, (unlocked - 1) * Stars.MAX)
            Spacer(Modifier.width(10.dp))
            RoundIconButton(HudIcons.Close, "Close levels", onClose, ButtonStyle.accent(palette), size = 42.dp)
        }
        LazyColumn(
            state = listState,
            modifier = Modifier.weight(1f).fillMaxWidth(),
            contentPadding = PaddingValues(top = 8.dp, bottom = 24.dp),
            verticalArrangement = Arrangement.spacedBy(18.dp),
        ) {
            items(MapLayout.sectionCount(unlocked), key = { it }) { section ->
                MapSection(section, game, pulse, onPick = { if (game.goToLevel(it)) onClose() })
            }
        }
    }
}

/** Header button that opens the level selector; sized to sit next to [PaletteButton]. */
@Composable
fun LevelsButton(onClick: () -> Unit) {
    RoundIconButton(HudIcons.Levels, "Levels", onClick, ButtonStyle.accent(LocalPalette.current), size = 44.dp)
}

/** All the stars earned so far, out of the most the solved levels could give. */
@Composable
private fun StarTotal(stars: Int, outOf: Int) {
    val palette = LocalPalette.current
    Row(
        Modifier
            .frosted(palette, RoundedCornerShape(50), elevation = 4.dp)
            .padding(start = 8.dp, end = 12.dp, top = 5.dp, bottom = 5.dp)
            .clearAndSetSemantics { contentDescription = "$stars of $outOf stars" },
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Canvas(Modifier.size(22.dp)) { drawStar(earned = true, emptyColor = palette.dimText) }
        Spacer(Modifier.width(5.dp))
        Text("$stars", color = palette.text, fontSize = 18.sp, fontWeight = FontWeight.Black)
        if (outOf > 0) Text(" / $outOf", color = palette.dimText, fontSize = 13.sp, fontWeight = FontWeight.Bold)
    }
}

/** One arena visit: a banner, then its levels along a dotted trail on a card in the arena's colors. */
@Composable
private fun MapSection(section: Int, game: GameController, pulse: State<Float>, onPick: (Int) -> Unit) {
    val first = MapLayout.firstLevel(section)
    val arena = Arena.of(first)
    val colors = arenaColors(arena)
    val levels = first until first + Arena.LEVELS
    val earned = levels.sumOf { game.stars[it] }
    BoxWithConstraints(
        Modifier
            .fillMaxWidth()
            .height(BannerHeight + RowHeight * Arena.LEVELS)
            .drawWithCache {
                val card = Brush.verticalGradient(
                    listOf(lerp(colors.light, Color.White, 0.55f), lerp(colors.light, Color.White, 0.25f), lerp(colors.light, colors.deep, 0.15f)),
                )
                val corner = CornerRadius(28.dp.toPx())
                val top = BannerHeight.toPx() / 2
                val row = RowHeight.toPx()
                val banner = BannerHeight.toPx()
                fun node(i: Int) = Offset(size.width * MapLayout.nodeX(i + 1), banner + row * i + row * 0.42f)
                val trail = Path().apply {
                    moveTo(size.width / 2, top)
                    for (i in 0 until Arena.LEVELS) {
                        val from = if (i == 0) Offset(size.width / 2, top) else node(i - 1)
                        val to = node(i)
                        val midY = (from.y + to.y) / 2
                        cubicTo(from.x, midY, to.x, midY, to.x, to.y)
                    }
                }
                val dot = 7.dp.toPx()
                val dots = Stroke(dot, cap = StrokeCap.Round, pathEffect = PathEffect.dashPathEffect(floatArrayOf(0.1f, dot * 2.1f)))
                val u = 1.7.dp.toPx()
                // Scattered pebbles of light, the same for a section every time.
                val pebbles = List(28) { k ->
                    Offset(size.width * noise(section * 97 + k), top + (size.height - top) * noise(section * 89 + k + 500)) to
                        (1.5f + 2.5f * noise(k + 1000)).dp.toPx()
                }
                onDrawBehind {
                    translate(top = top) {
                        drawRoundRect(Color.Black.copy(alpha = 0.18f), Offset(0f, 5.dp.toPx()), size.copy(height = size.height - top), corner)
                        drawRoundRect(card, size = size.copy(height = size.height - top), cornerRadius = corner)
                        drawRoundRect(Color.White.copy(alpha = 0.7f), size = size.copy(height = size.height - top), cornerRadius = corner, style = Stroke(2.dp.toPx()))
                    }
                    for ((p, radius) in pebbles) drawCircle(Color.White.copy(alpha = 0.35f), radius, p)
                    // Little emblems by the trail, on the side away from the nodes.
                    for (i in 0 until Arena.LEVELS step 2) {
                        val n = node(i)
                        val x = if (n.x > size.width / 2) size.width * 0.14f else size.width * 0.86f
                        drawEmblem(arena, Offset(x, n.y + row * 0.45f), u)
                    }
                    translate(top = 2.dp.toPx()) { drawPath(trail, colors.deep.copy(alpha = 0.35f), style = dots) }
                    drawPath(trail, Color.White, style = dots)
                }
            },
    ) {
        val width = maxWidth
        SectionBanner(section, arena, earned)
        for (i in 0 until Arena.LEVELS) {
            val number = first + i
            Box(
                Modifier
                    .offset(x = width * MapLayout.nodeX(i + 1) - NodeSlot / 2, y = BannerHeight + RowHeight * i + RowHeight * 0.42f - NodeSize / 2)
                    .width(NodeSlot),
                contentAlignment = Alignment.TopCenter,
            ) {
                LevelNode(number, game, pulse, onPick)
            }
        }
    }
}

@Composable
private fun SectionBanner(section: Int, arena: Arena, earned: Int) {
    val colors = arenaColors(arena)
    val shape = RoundedCornerShape(22.dp)
    Row(
        Modifier
            .fillMaxWidth()
            .padding(horizontal = 10.dp)
            .height(58.dp)
            .drawWithCache {
                val corner = CornerRadius(22.dp.toPx())
                val lip = 5.dp.toPx()
                val face = size.copy(height = size.height - lip)
                val fill = Brush.verticalGradient(listOf(lerp(colors.light, Color.White, 0.2f), colors.deep), 0f, face.height)
                onDrawBehind {
                    drawRoundRect(Color.Black.copy(alpha = 0.2f), Offset(0f, lip + 2.dp.toPx()), face, corner)
                    drawRoundRect(lerp(colors.deep, Color.Black, 0.3f), Offset(0f, lip), face, corner)
                    drawRoundRect(fill, size = face, cornerRadius = corner)
                    drawRoundRect(Color.White.copy(alpha = 0.25f), Offset(face.width * 0.06f, 4.dp.toPx()), face.copy(width = face.width * 0.88f, height = face.height * 0.36f), CornerRadius(12.dp.toPx()))
                    drawRoundRect(Color.White.copy(alpha = 0.6f), size = face, cornerRadius = corner, style = Stroke(1.5.dp.toPx()))
                }
            }
            .padding(start = 8.dp, end = 16.dp, bottom = 5.dp)
            .semantics(mergeDescendants = true) { heading() },
        verticalAlignment = Alignment.CenterVertically,
    ) {
        ArenaBadge(arena, Modifier.size(44.dp))
        Spacer(Modifier.width(10.dp))
        Text(
            MapLayout.title(section),
            color = Color.White,
            fontSize = 21.sp,
            fontWeight = FontWeight.Black,
            maxLines = 1,
            style = LocalTextStyle.current.copy(shadow = Shadow(colors.deep, Offset(0f, 3f), 2f)),
            modifier = Modifier.weight(1f),
        )
        Row(
            Modifier
                .background(Color.Black.copy(alpha = 0.18f), shape)
                .padding(horizontal = 8.dp, vertical = 3.dp)
                .clearAndSetSemantics { contentDescription = "$earned of ${Arena.LEVELS * Stars.MAX} stars" },
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Canvas(Modifier.size(16.dp)) { drawStar(earned = true, emptyColor = Color.White) }
            Spacer(Modifier.width(4.dp))
            Text("$earned/${Arena.LEVELS * Stars.MAX}", color = Color.White, fontSize = 13.sp, fontWeight = FontWeight.ExtraBold)
        }
    }
}

/** One level on the trail: a round button with its number (or a lock), and its best stars underneath. */
@Composable
private fun LevelNode(number: Int, game: GameController, pulse: State<Float>, onPick: (Int) -> Unit) {
    val unlocked = game.unlockedLevel
    val solved = number < unlocked
    val current = number == unlocked
    val locked = number > unlocked
    val open = number == game.levelNumber
    val stars = game.stars[number]
    val arena = Arena.of(number)
    val style = when {
        current -> ButtonStyle(NextGold)
        locked -> ButtonStyle(Color(0xFFB9B4AE), Color.White)
        else -> ButtonStyle(arenaColors(arena).deep, Color.White)
    }
    Column(horizontalAlignment = Alignment.CenterHorizontally) {
        Box(contentAlignment = Alignment.Center) {
            if (open) {
                // A soft white halo marks the level being played.
                Box(Modifier.size(NodeSize + 10.dp).background(Color.White.copy(alpha = 0.75f), CircleShape))
            }
            GameButton(
                onClick = { onPick(number) },
                style = style,
                shape = CircleShape,
                enabled = !locked,
                lip = 5.dp,
                label = "Level $number",
                modifier = Modifier
                    .graphicsLayer {
                        val s = if (current) 1f + 0.06f * pulse.value else 1f
                        scaleX = s
                        scaleY = s
                    }
                    .size(NodeSize, NodeSize + 5.dp)
                    .semantics {
                        stateDescription = when {
                            solved -> "solved, $stars of ${Stars.MAX} stars"
                            current -> "next to solve"
                            else -> "locked"
                        } + if (open) ", playing" else ""
                    },
            ) {
                if (locked) {
                    Image(rememberVectorPainter(HudIcons.Lock), null, Modifier.size(22.dp), colorFilter = ColorFilter.tint(Color.White))
                } else {
                    Text(
                        "$number",
                        color = style.content,
                        fontSize = if (number < 100) 24.sp else 18.sp,
                        fontWeight = FontWeight.Black,
                        style = LocalTextStyle.current.copy(shadow = Shadow(Color.Black.copy(alpha = 0.25f), Offset(0f, 2f), 2f)),
                    )
                }
            }
        }
        if (solved) StarRow(stars, Color.Black.copy(alpha = 0.35f), Modifier.offset(y = (-6).dp), size = 18.dp, gap = 0.dp)
        else if (open || current) PlayingTag(if (open) "Playing" else "Next")
    }
}

@Composable
private fun PlayingTag(text: String) {
    Text(
        text.uppercase(),
        color = Color.White,
        fontSize = 10.sp,
        fontWeight = FontWeight.Black,
        letterSpacing = 0.6.sp,
        modifier = Modifier
            .offset(y = (-4).dp)
            .background(Color(0xFFE8574A), RoundedCornerShape(50))
            .padding(horizontal = 8.dp, vertical = 2.dp)
            .clearAndSetSemantics { },
    )
}

/** A pseudo-random number in 0..1 for [seed], always the same for the same seed. */
private fun noise(seed: Int): Float {
    val x = sin(seed * 12.9898f) * 43758.547f
    return x - floor(x)
}
