/** The colors of a [GameButton]: its [face], and the [content] (icon or text) on it. The lip is a darker face. */
class ButtonStyle(val face: Color, val content: Color = readableOn(face)) {
    companion object {
        /** The everyday button: the palette's accent. */
        fun accent(palette: Palette) = ButtonStyle(palette.accent, palette.onAccent)

        /** The button that helps: the palette's highlight. */
        fun bright(palette: Palette) = ButtonStyle(palette.highlight)

        /** The button that moves the player on: the palette's "done" green. */
        fun go(palette: Palette) = ButtonStyle(palette.done)
    }
}

/** White, or a deep shade of [face]: whichever has the higher WCAG contrast ratio against it. */
fun readableOn(face: Color): Color {
    val dark = lerp(face, Color.Black, 0.8f)
    return if (contrastRatio(face, dark) > contrastRatio(face, Color.White)) dark else Color.White
}

/** The WCAG contrast ratio of two opaque colors, from 1 (same) to 21 (black on white). */
fun contrastRatio(a: Color, b: Color): Float {
    val la = a.luminance()
    val lb = b.luminance()
    return (maxOf(la, lb) + 0.05f) / (minOf(la, lb) + 0.05f)
}

/**
 * A chunky game button: a glossy [shape] face resting on a darker lip of [lip] height, which gives it depth.
 * Pressing squashes the face down onto the lip; a disabled button turns grayish and its gloss dims.
 * Keyboard focus draws a ring around the button.
 * [label] is read by screen readers when the content is only an icon.
 */
@Composable
fun GameButton(
    onClick: () -> Unit,
    style: ButtonStyle,
    modifier: Modifier = Modifier,
    shape: Shape = RoundedCornerShape(50),
    enabled: Boolean = true,
    lip: Dp = 4.dp,
    label: String? = null,
    content: @Composable BoxScope.() -> Unit,
) {
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    val focused by interaction.collectIsFocusedAsState()
    val press by animateFloatAsState(
        if (pressed && enabled) 1f else 0f,
        spring(dampingRatio = 0.45f, stiffness = Spring.StiffnessMedium),
    )
    val face = if (enabled) style.face else lerp(style.face, Color.Gray, 0.55f)
    val lipColor = lerp(face, Color.Black, 0.38f)
    Box(
        modifier
            .clickable(interaction, indication = null, enabled = enabled, role = Role.Button, onClick = onClick)
            .then(if (label != null) Modifier.semantics { contentDescription = label } else Modifier)
            .drawWithCache {
                val lipPx = lip.toPx()
                val faceSize = Size(size.width, size.height - lipPx)
                val outline = shape.createOutline(faceSize, layoutDirection, this)
                // The focus ring: white on a dark edge, so it shows on any background.
                val gap = 4.dp.toPx()
                val ring = shape.createOutline(Size(size.width + 2 * gap, size.height + 2 * gap), layoutDirection, this)
                val ringEdge = Stroke(5.dp.toPx())
                val ringLine = Stroke(2.5.dp.toPx())
                onDrawBehind {
                    // A soft contact shadow, then the lip the face sits on.
                    translate(top = lipPx + 1.5.dp.toPx()) { drawOutline(outline, Color.Black.copy(alpha = 0.18f)) }
                    translate(top = lipPx) { drawOutline(outline, lipColor) }
                    if (focused) {
                        translate(-gap, -gap) {
                            drawOutline(ring, Color.Black.copy(alpha = 0.55f), style = ringEdge)
                            drawOutline(ring, Color.White, style = ringLine)
                        }
                    }
                }
            },
    ) {
        Box(
            Modifier
                .fillMaxSize()
                .padding(bottom = lip)
                .graphicsLayer {
                    translationY = lip.toPx() * press
                    scaleX = 1f + 0.04f * press
                    scaleY = 1f - 0.05f * press
                    transformOrigin = TransformOrigin(0.5f, 1f)
                }
                .drawWithCache {
                    val outline = shape.createOutline(size, layoutDirection, this)
                    val body = Brush.verticalGradient(
                        0f to lerp(face, Color.White, 0.28f),
                        0.55f to face,
                        1f to lerp(face, Color.Black, 0.12f),
                    )
                    // The gloss: a bright band over the upper half, inset from the edges.
                    val inset = size.minDimension * 0.12f
                    val glossSize = Size(size.width - 2 * inset, size.height * 0.42f)
                    val gloss = shape.createOutline(glossSize, layoutDirection, this)
                    val glossBrush = Brush.verticalGradient(
                        listOf(Color.White.copy(alpha = if (enabled) 0.55f else 0.2f), Color.White.copy(alpha = 0.04f)),
                        startY = 0f,
                        endY = glossSize.height,
                    )
                    val rim = Stroke(1.2.dp.toPx())
                    onDrawBehind {
                        drawOutline(outline, body)
                        translate(left = inset, top = size.height * 0.07f) { drawOutline(gloss, glossBrush) }
                        drawOutline(outline, lerp(face, Color.Black, 0.3f).copy(alpha = 0.6f), style = rim)
                    }
                },
            contentAlignment = Alignment.Center,
            content = content,
        )
    }
}

/** A round [GameButton] showing [icon]; with [caption], its [label] is also written underneath. */
@Composable
fun RoundIconButton(
    icon: ImageVector,
    label: String,
    onClick: () -> Unit,
    style: ButtonStyle,
    modifier: Modifier = Modifier,
    enabled: Boolean = true,
    size: Dp = 48.dp,
    caption: Boolean = false,
) {
    val palette = LocalPalette.current
    Column(modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        GameButton(
            onClick = onClick,
            style = style,
            shape = CircleShape,
            enabled = enabled,
            lip = size * 0.09f,
            label = label,
            modifier = Modifier.size(size, size * 1.09f),
        ) {
            Image(
                rememberVectorPainter(icon),
                contentDescription = null,
                colorFilter = ColorFilter.tint(if (enabled) style.content else style.content.copy(alpha = 0.55f)),
                modifier = Modifier.size(size * 0.54f),
            )
        }
        if (caption) {
            Spacer(Modifier.height(2.dp))
            Text(
                label,
                color = if (enabled) palette.text else palette.dimText.copy(alpha = 0.5f),
                fontSize = 11.sp,
                fontWeight = FontWeight.Bold,
                maxLines = 1,
                // The button already reads its label.
                modifier = Modifier.clearAndSetSemantics { },
            )
        }
    }
}

/** A text-only pill [GameButton], for the main call to action on a card. */
@Composable
fun PillButton(text: String, onClick: () -> Unit, style: ButtonStyle, modifier: Modifier = Modifier, enabled: Boolean = true) {
    GameButton(onClick, style, modifier.height(54.dp), enabled = enabled, lip = 5.dp) {
        Text(
            text,
            color = style.content,
            fontSize = 19.sp,
            fontWeight = FontWeight.ExtraBold,
            modifier = Modifier.padding(horizontal = 30.dp),
        )
    }
}
