package io.colorsand.core

/**
 * Stars for a solved level, 1 to 3, by how many moves it took against the level's par.
 *
 * Par is the shortest solution plus a little [slack], so a careful player can earn 3 stars without finding
 * the very best line. Following the hints from the start also stays within par.
 */
object Stars {
    const val MAX = 3

    /** 3 stars at or under [par], 2 stars up to a quarter more (and at least 2 more), otherwise 1. */
    fun earned(moves: Int, par: Int?): Int = when {
        par == null || moves <= par -> 3
        moves <= par + maxOf(2, par / 4) -> 2
        else -> 1
    }

    /** The moves allowed over a solution of [shortest] moves: one for every 8, rounded up. */
    fun slack(shortest: Int): Int = (shortest + 7) / 8

    /**
     * The fewest moves that solve each designed level, found by an exhaustive A* search ([Planner] with
     * weight 1), so the game never searches for them. `StarsTest` checks them.
     */
    internal val SHORTEST = listOf(
        3, 9, 13, 12, 16, 16, 18, 16, 20, 21, // Playground
        18, 18, 15, 20, 17, 24, 18, 25, 19, 24, // Beach
        30, 32, 38, 37, 37, 39, 41, 40, 42, 46, // Desert
    )

    private val pars = HashMap<Int, Int?>()

    /**
     * The par for level [number], or null if no solution was found. Endless levels use the length of a
     * near-shortest solution instead, found the first time it is asked for. Cached; call it from one thread.
     */
    fun par(number: Int): Int? {
        // getOrPut would search again every time for a cached null.
        if (number in pars) return pars[number]
        val shortest = SHORTEST.getOrNull(number - 1)
            ?: Planner.plan(Levels[number].board)?.size
            ?: Solver.solve(Levels[number].board)?.size
        return shortest?.let { it + slack(it) }.also { pars[number] = it }
    }
}
