package io.colorsand.core

import kotlin.random.Random

/**
 * What a level is made of: [colors] colors in tubes of [capacity], plus [spareTubes] empty tubes.
 * [towers] of the filled tubes start with [towerHeight] units of one color at the bottom: nearly built
 * towers that tempt the player to finish them before their last units are dug out.
 */
data class LevelSpec(
    val colors: Int,
    val capacity: Int = 4,
    val spareTubes: Int = 2,
    val towers: Int = 0,
    val towerHeight: Int = 0,
) {
    init {
        require(colors in 2..SandColor.entries.size) { "colors must be in 2..${SandColor.entries.size}" }
        require(towers in 0..colors) { "towers must be in 0..$colors" }
        require(towers == 0 || towerHeight in 1 until capacity) { "towerHeight must be in 1 until $capacity" }
    }

    val tubes: Int get() = colors + spareTubes
}

/**
 * Generates random solvable levels. The same level number always yields the same level on every platform.
 *
 * [specFor] holds the rules of each arena: the Playground has tubes of 4 and two spare tubes; the Beach adds
 * towers and, on every other level, a low tide with only one spare tube; the Desert has tubes of 5. Changing
 * anything here changes the endless levels players may be on, so `LevelsTest` pins a few of them.
 */
object LevelGenerator {
    /** At most this many tubes fit on screen (two rows of 7). */
    const val MAX_TUBES = 14

    /** Low-tide levels with more colors than this are almost never solvable. */
    const val MAX_LOW_TIDE_COLORS = 9

    private const val MAX_ATTEMPTS = 2_000

    /** Colors in the order levels use them: the first few are the easiest to tell apart. */
    private val COLOR_ORDER: List<SandColor> = "RBYGPOKCNLAW".map(SandColor::fromCode)

    /** Enough to find a solution or prove there is none for nearly every board; others are skipped. */
    private const val SOLVER_BUDGET = 100_000

    /**
     * The rules for endless level [number] (past the designed ones): its arena's rules, with one more color
     * each time the arenas come round again, up to the palette size. In each arena the colors rise from
     * level to level, so its first level is a little easier than the last arena's final one.
     */
    fun specFor(number: Int): LevelSpec {
        require(number >= 1) { "Level numbers start at 1, was $number" }
        val round = (number - 1) / (Arena.LEVELS * Arena.entries.size)
        val stage = Arena.stage(number)
        val ramp = (stage - 1) / 3 // 0, 0, 0, 1, 1, 1, 2, 2, 2, 3
        val max = SandColor.entries.size
        return when (Arena.of(number)) {
            Arena.PLAYGROUND -> LevelSpec(colors = minOf(max, 6 + round + ramp))
            Arena.BEACH -> {
                val colors = minOf(max, 7 + round + ramp)
                if (stage % 2 == 1 && stage > 1) {
                    val lowTide = minOf(colors, MAX_LOW_TIDE_COLORS)
                    LevelSpec(lowTide, spareTubes = 1, towers = lowTide / 2, towerHeight = 3)
                } else {
                    LevelSpec(colors, towers = colors / 3, towerHeight = 2)
                }
            }
            Arena.DESERT -> LevelSpec(colors = minOf(max, 7 + round + ramp), capacity = 5)
        }
    }

    /** Level [number], made to [spec] from [seed]. The board is checked to be solvable. */
    fun generate(number: Int, spec: LevelSpec = specFor(number), seed: Long = number.toLong()): Level {
        require(number >= 1) { "Level numbers start at 1, was $number" }
        require(spec.tubes <= MAX_TUBES) { "Level $number would have ${spec.tubes} tubes, at most $MAX_TUBES fit" }
        val random = Random(seed)
        repeat(MAX_ATTEMPTS) {
            val board = deal(spec, random)
            if (board != null && Solver.search(board, SOLVER_BUDGET) is SolveResult.Solution) return Level(number, board)
        }
        error("No solvable level found for level $number with $spec")
    }

    /** One random board to [spec], or null if a tube came out already sorted. */
    private fun deal(spec: LevelSpec, random: Random): Board? {
        val palette = COLOR_ORDER.take(spec.colors)
        val towerColors = palette.toMutableList().also { shuffle(it, random) }.take(spec.towers)
        val loose = palette.flatMap { color ->
            List(spec.capacity - if (color in towerColors) spec.towerHeight else 0) { color }
        }.toMutableList()
        shuffle(loose, random)
        var next = 0
        val filled = palette.indices.map { i ->
            val base = if (i < towerColors.size) List(spec.towerHeight) { towerColors[i] } else emptyList()
            val top = loose.subList(next, next + spec.capacity - base.size).toList()
            next += top.size
            Tube(spec.capacity, base + top)
        }.toMutableList()
        if (filled.any { it.isSorted }) return null
        shuffle(filled, random)
        return Board(filled + List(spec.spareTubes) { Tube(spec.capacity) })
    }

    /** Fisher-Yates, written out so the result only depends on [Random]'s output, not on library internals. */
    private fun <T> shuffle(list: MutableList<T>, random: Random) {
        for (i in list.lastIndex downTo 1) {
            val j = random.nextInt(i + 1)
            val tmp = list[i]
            list[i] = list[j]
            list[j] = tmp
        }
    }
}
