/**
 * Arriving in an arena: [level] is the first one played there. [cleared] when the player got here by solving the
 * last level of the arena before, which earns a sweep of light across the screen before the banner.
 */
data class ArenaArrival(val level: Int, val cleared: Boolean) {
    val arena: Arena get() = Arena.of(level)

    companion object {
        /**
         * The arrival to show when the game moves from level [previous] to [level], with [moves] made on it, or null.
         * [previous] is null when the game has just opened.
         * - Opening the game on an arena's first level before any move introduces the arena; opening it mid-arena
         *   doesn't, so a restart never repeats the banner.
         * - Going on from an arena's last level to the next level clears the arena and introduces the next one.
         * - Jumping into another arena (say, from the level list) introduces it.
         * - Anything else (a restart, another level of the same arena) shows nothing.
         */
        fun of(previous: Int?, level: Int, moves: Int): ArenaArrival? = when {
            previous == null -> if (Arena.isFirst(level) && moves == 0) ArenaArrival(level, cleared = false) else null
            previous == level -> null
            level == previous + 1 && Arena.isLast(previous) -> ArenaArrival(level, cleared = true)
            Arena.of(level) != Arena.of(previous) -> ArenaArrival(level, cleared = false)
            else -> null
        }
    }
}

/**
 * Shows the arena's banner whenever the player arrives in an arena (see [ArenaArrival.of]): it sweeps in with the
 * arena's name and a tagline and leaves after a moment or on a tap. Sits over the board, under the level-complete card.
 */
@Composable
fun ArenaIntro(game: GameController) {
    // The level last looked at survives rotation, so turning the phone doesn't bring the banner back.
    var seen by rememberSaveable { mutableStateOf<Int?>(null) }
    var arrival by remember { mutableStateOf<ArenaArrival?>(null) }
    val level = game.levelNumber
    LaunchedEffect(level) {
        ArenaArrival.of(seen, level, game.moveCount)?.let { arrival = it }
        seen = level
    }
    arrival?.let { shown -> key(shown) { ArenaBanner(shown, onDone = { arrival = null }) } }
}

/** How long the banner stays up before it leaves by itself. */
private const val HOLD_MS = 2500L
private const val SWEEP_MS = 1100

@Composable
private fun ArenaBanner(arrival: ArenaArrival, onDone: () -> Unit) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val look = remember(arrival.arena, palette) { BannerLook.of(arrival.arena, grade, light = palette.isLight, ink = palette.text) }
    val sweep = remember { Animatable(if (arrival.cleared) 0f else 1f) }
    // -1: off to the left, 0: in place, 1: gone to the right.
    val slide = remember { Animatable(-1f) }
    val sparkle = remember { Animatable(0f) }
    val tapped = remember { CompletableDeferred<Unit>() }
    LaunchedEffect(Unit) {
        val show = launch {
            if (arrival.cleared) sweep.animateTo(1f, tween(SWEEP_MS, easing = LinearEasing))
            launch { sparkle.animateTo(1f, tween(HOLD_MS.toInt() + 600, easing = LinearEasing)) }
            slide.animateTo(0f, spring(dampingRatio = 0.68f, stiffness = Spring.StiffnessLow))
            delay(HOLD_MS)
        }
        select<Unit> {
            show.onJoin {}
            tapped.onAwait {}
        }
        show.cancel()
        sweep.snapTo(1f)
        slide.animateTo(1f, tween(360, easing = FastOutLinearInEasing))
        onDone()
    }
    Box(
        Modifier
            .fillMaxSize()
            .clickable(remember { MutableInteractionSource() }, indication = null) { tapped.complete(Unit) },
    ) {
        if (sweep.value < 1f) LightSweep(sweep.value, Modifier.matchParentSize())
        BoxWithConstraints(Modifier.matchParentSize(), contentAlignment = Alignment.TopCenter) {
            val offset = slide.value
            Box(
                Modifier
                    .padding(top = maxHeight * 0.3f)
                    .graphicsLayer {
                        translationX = offset * size.width * 1.4f
                        rotationZ = -3f * offset
                    }
                    .alpha(if (slide.value == -1f) 0f else 1f - max(0f, offset)),
                contentAlignment = Alignment.Center,
            ) {
                Ribbon(arrival, look, sparkle.value)
            }
        }
    }
}

/** A wide band of warm light sweeping across the screen at [progress], while the scenery cross-fades under it. */
@Composable
private fun LightSweep(progress: Float, modifier: Modifier) {
    Canvas(modifier) {
        val x = -size.width * 0.8f + progress * size.width * 2.6f
        val band = size.width * 0.7f
        drawRect(Color(0xFFFFF4D6).copy(alpha = 0.35f * (1f - progress) * progress * 4f))
        drawRect(
            Brush.linearGradient(
                0f to Color.Transparent,
                0.5f to Color(0xCCFFF6DE),
                1f to Color.Transparent,
                start = Offset(x - band, 0f),
                end = Offset(x, size.height * 0.35f),
            ),
        )
    }
}

/** The colors of an arena's banner, graded like its scenery. */
private class BannerLook(val top: Color, val bottom: Color, val tail: Color, val text: Color, val shadow: Color) {
    companion object {
        /** On a [light] scheme the wash makes the ribbon pale, so its text takes the scheme's dark [ink]. */
        fun of(arena: Arena, g: SceneGrade, light: Boolean, ink: Color): BannerLook {
            val (top, bottom, tail) = when (arena) {
                Arena.PLAYGROUND -> Triple(0xFF72CC5C, 0xFF3F9C46, 0xFF2E7A36)
                Arena.BEACH -> Triple(0xFF3CC9D3, 0xFF1C93B0, 0xFF136F8C)
                Arena.DESERT -> Triple(0xFFF59A4A, 0xFFD3632E, 0xFFA2441F)
            }
            return if (light) {
                BannerLook(g(top), g(bottom), g(tail), ink, Color.White.copy(alpha = 0.5f))
            } else {
                BannerLook(g(top), g(bottom), g(tail), Color.White, lerp(g(tail), Color.Black, 0.45f).copy(alpha = 0.55f))
            }
        }
    }
}

private fun tagline(arena: Arena): String = when (arena) {
    Arena.PLAYGROUND -> "Swings, slides and a sandbox"
    Arena.BEACH -> "Seashells and a warm sea breeze"
    Arena.DESERT -> "Golden dunes at dusk"
}

@Composable
private fun Ribbon(arrival: ArenaArrival, look: BannerLook, sparkle: Float) {
    val first = (arrival.level - 1) / Arena.LEVELS * Arena.LEVELS + 1
    Box(Modifier.widthIn(max = 420.dp).padding(horizontal = 8.dp), contentAlignment = Alignment.Center) {
        Canvas(Modifier.matchParentSize()) { drawRibbon(look, sparkle) }
        Column(
            Modifier.padding(horizontal = 56.dp, vertical = 14.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
        ) {
            Text(
                "LEVELS $first–${first + Arena.LEVELS - 1}",
                color = look.text.copy(alpha = 0.85f),
                fontSize = 12.sp,
                fontWeight = FontWeight.Bold,
                letterSpacing = 2.sp,
            )
            Text(
                "The ${arrival.arena.title}",
                style = TextStyle(shadow = Shadow(look.shadow, Offset(0f, 4f), 6f)),
                color = look.text,
                fontSize = 34.sp,
                fontWeight = FontWeight.ExtraBold,
                textAlign = TextAlign.Center,
            )
            Text(
                tagline(arrival.arena),
                color = look.text.copy(alpha = 0.92f),
                fontSize = 14.sp,
                textAlign = TextAlign.Center,
            )
        }
    }
}

/** A glossy ribbon banner with folded tails behind both ends, and a few twinkles around it at [sparkle]. */
private fun DrawScope.drawRibbon(look: BannerLook, sparkle: Float) {
    val w = size.width
    val h = size.height
    val tailW = h * 0.5f
    val inset = tailW * 0.75f
    val tailTop = h * 0.32f
    val tailBottom = h * 1.12f
    // Tails: lower than the body, tucked under its ends, with a notch cut into their outer end.
    for (side in listOf(-1f, 1f)) {
        val edge = if (side < 0) inset else w - inset
        val inner = edge - side * h * 0.2f
        val outer = edge + side * tailW
        val tail = Path().apply {
            moveTo(inner, tailTop)
            lineTo(outer, tailTop)
            lineTo(outer - side * tailW * 0.3f, (tailTop + tailBottom) / 2)
            lineTo(outer, tailBottom)
            lineTo(inner, tailBottom)
            close()
        }
        drawPath(tail, look.tail)
        // The fold where the tail tucks under the body.
        val fold = Path().apply {
            moveTo(edge, h)
            lineTo(edge, tailBottom)
            lineTo(edge + side * h * 0.16f, tailBottom)
            close()
        }
        drawPath(fold, look.shadow.copy(alpha = 0.9f))
    }
    val corner = CornerRadius(h * 0.22f)
    val left = inset
    val bodyW = w - 2 * inset
    drawRoundRect(look.shadow.copy(alpha = 0.35f), Offset(left, h * 0.08f), Size(bodyW, h), corner)
    drawRoundRect(Brush.verticalGradient(listOf(look.top, look.bottom)), Offset(left, 0f), Size(bodyW, h), corner)
    // Gloss over the upper half and a bright rim along the top.
    drawRoundRect(Color.White.copy(alpha = 0.16f), Offset(left + h * 0.06f, h * 0.05f), Size(bodyW - h * 0.12f, h * 0.42f), CornerRadius(h * 0.18f))
    drawRoundRect(Color.White.copy(alpha = 0.45f), Offset(left, 0f), Size(bodyW, h), corner, style = Stroke(h * 0.025f))
    // Twinkles: four-pointed stars that grow and fade at the corners.
    val spots = listOf(Offset(left + h * 0.1f, -h * 0.08f), Offset(w - left - h * 0.15f, h * 0.05f), Offset(w * 0.62f, -h * 0.14f), Offset(left + bodyW * 0.18f, h * 1.12f))
    for ((i, p) in spots.withIndex()) {
        val local = ((sparkle * 3f - i * 0.35f) % 1f + 1f) % 1f
        val s = h * 0.13f * kotlin.math.sin(local * kotlin.math.PI.toFloat())
        if (s <= 0f) continue
        rotate(local * 90f, p) {
            val star = Path().apply {
                moveTo(p.x, p.y - s)
                quadraticTo(p.x, p.y, p.x + s, p.y)
                quadraticTo(p.x, p.y, p.x, p.y + s)
                quadraticTo(p.x, p.y, p.x - s, p.y)
                quadraticTo(p.x, p.y, p.x, p.y - s)
                close()
            }
            drawPath(star, Color(0xFFFFF6D8))
        }
    }
}
