/**
 * The first-time tutorial, drawn over the board: a cartoon glove taps the tube to pick up and then the tube
 * to pour into, along the hint's first pour, with a caption on a frosted pill. Put it on the board's
 * modifier (the board's own layout, so tube places line up) after the board has been placed.
 *
 * It shows on level 1 until the first pour, and only while level 1 has never been solved.
 */
@Composable
fun Modifier.tutorial(game: GameController, pours: PourAnimation): Modifier {
    val showing = showsTutorial(game.levelNumber, game.moveCount, game.unlockedLevel, game.isSolved)
    val fade by animateFloatAsState(if (showing) 1f else 0f, tween(if (showing) 500 else 250))
    if (!showing && fade == 0f) return this
    val first = remember(game.levelNumber) { (GameSession(Levels[game.levelNumber]).hint() as? Hint.Pour)?.move }
    val clock = rememberInfiniteTransition().animateFloat(
        initialValue = 0f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(tween(TUTORIAL_MILLIS, easing = LinearEasing)),
    )
    val measurer = rememberTextMeasurer()
    val captions = remember(measurer) {
        val style = TextStyle(color = CAPTION_TEXT, fontSize = 16.sp, fontWeight = FontWeight.SemiBold)
        listOf(PICK_UP, POUR).map { measurer.measure(it, style) }
    }
    val board = game.board
    val selected = game.selected
    return drawWithContent {
        drawContent()
        val plan = first ?: return@drawWithContent
        val bounds = board.tubes.indices.map { pours.tubeBounds(it) ?: return@drawWithContent }
        val gesture = tutorialGesture(board, plan, selected)
        val frame = gestureFrame(gesture, clock.value)
        val alpha = fade * frame.alpha
        val tubeWidth = bounds.first().width
        val point = { tube: Int -> bounds[tube].let { Offset(it.center.x, it.top + it.height * 0.42f) } }
        val tip = lerp(point(gesture.first), point(gesture.second), frame.travel)
        val pill = captions[if (frame.pickUp) 0 else 1]
        // Above the tubes, clear of one the paw lifts.
        drawCaption(pill, Offset(size.width / 2, bounds.minOf { it.top } - tubeWidth * 1.3f), fade)
        if (frame.ripple > 0f) drawRipple(tip, tubeWidth, frame.ripple, alpha)
        drawGlove(tip + Offset(0f, tubeWidth * 0.08f * frame.press), tubeWidth * 1.55f, 1f - 0.12f * frame.press, alpha)
    }
}

/** Whether the tutorial shows: on level 1 before the first pour, until level 1 has been solved once. */
internal fun showsTutorial(level: Int, moves: Int, unlockedLevel: Int, solved: Boolean): Boolean =
    level == 1 && moves == 0 && unlockedLevel <= 1 && !solved

/**
 * What the glove shows: a tap on [first] and then, if [second] differs, a tap on [second].
 * With nothing picked up it shows the whole pour; once a tube is picked up, only where to pour it.
 */
internal data class Gesture(val first: Int, val second: Int)

internal fun tutorialGesture(board: Board, plan: Move, selected: Int?): Gesture {
    if (selected == null) return Gesture(plan.from, plan.to)
    val target = plan.to.takeIf { board.canPour(selected, it) }
        ?: board.tubes.indices.firstOrNull { board.canPour(selected, it) }
        ?: plan.to
    return Gesture(target, target)
}

/**
 * The glove at one moment of the loop: [travel] from the first tube (0) to the second (1), how far it
 * [press]es down, the tap's [ripple] (0 when none), its [alpha], and whether the caption is [pickUp].
 */
internal data class GestureFrame(val travel: Float, val press: Float, val ripple: Float, val alpha: Float, val pickUp: Boolean)

/** The glove at [t] (0 to 1) through one loop of [gesture]. */
internal fun gestureFrame(gesture: Gesture, t: Float): GestureFrame {
    val alpha = minOf(phase(t, 0f, 0.08f), 1f - phase(t, 0.9f, 1f))
    if (gesture.first == gesture.second) {
        val tap = phase(t, 0.2f, 0.38f)
        return GestureFrame(0f, bump(tap), ripple(tap), alpha, pickUp = false)
    }
    val firstTap = phase(t, 0.12f, 0.26f)
    val secondTap = phase(t, 0.6f, 0.74f)
    val travel = smoothStep(phase(t, 0.32f, 0.56f))
    return GestureFrame(
        travel = travel,
        press = bump(firstTap) + bump(secondTap),
        ripple = if (t < 0.45f) ripple(firstTap) else ripple(secondTap),
        alpha = alpha,
        pickUp = t < 0.44f,
    )
}

private const val TUTORIAL_MILLIS = 2_800
private const val PICK_UP = "Tap a tube to pick it up"
private const val POUR = "Tap another to pour"
private val CAPTION_TEXT = Color(0xFF2E2840)
private val GLOVE = Color.White
private val GLOVE_SHADE = Color(0xFFE6E9F2)
private val CUFF = Color(0xFFDDE3F0)
private val OUTLINE = Color(0xFF2E2840)

/** A press that goes down and comes back up over a tap's [f] (0 to 1). */
private fun bump(f: Float): Float = sin(PI.toFloat() * f).coerceAtLeast(0f)

/** The ring a tap leaves, from the moment the finger touches (0 while it hasn't yet). */
private fun ripple(f: Float): Float = phase(f, 0.4f, 1f)

private fun smoothStep(x: Float): Float = x * x * (3 - 2 * x)

private fun lerp(a: Offset, b: Offset, f: Float) = a + (b - a) * f

private fun DrawScope.drawCaption(text: TextLayoutResult, center: Offset, alpha: Float) {
    val padX = 18.dp.toPx()
    val padY = 10.dp.toPx()
    val size = Size(text.size.width + padX * 2, text.size.height + padY * 2)
    val topLeft = Offset(center.x - size.width / 2, center.y - size.height)
    val corner = CornerRadius(size.height / 2)
    drawRoundRect(Color.Black.copy(alpha = 0.14f * alpha), topLeft + Offset(0f, 3.dp.toPx()), size, corner)
    // Frosted glass: milky, brighter at the top, with a crisp rim.
    val frost = Brush.verticalGradient(
        listOf(Color.White.copy(alpha = 0.92f * alpha), Color.White.copy(alpha = 0.7f * alpha)),
        startY = topLeft.y,
        endY = topLeft.y + size.height,
    )
    drawRoundRect(frost, topLeft, size, corner)
    drawRoundRect(Color.White.copy(alpha = alpha), topLeft, size, corner, style = Stroke(1.5.dp.toPx()))
    drawText(text, topLeft = topLeft + Offset(padX, padY), alpha = alpha)
}

private fun DrawScope.drawRipple(at: Offset, tubeWidth: Float, f: Float, alpha: Float) {
    val radius = tubeWidth * (0.15f + 0.45f * f)
    drawCircle(Color.White.copy(alpha = 0.8f * (1f - f) * alpha), radius, at, style = Stroke(tubeWidth * 0.07f))
}

/** A plump cartoon glove pointing up, its fingertip at [tip], [height] tall from fingertip to cuff. */
private fun DrawScope.drawGlove(tip: Offset, height: Float, scale: Float, alpha: Float) {
    if (alpha <= 0f) return
    val s = height
    val outline = s * 0.035f
    val pieces = gloveShapes(s)
    // Each part is drawn opaque into a layer that is then faded as a whole, so overlaps don't show through.
    fun layer(opacity: Float, draw: DrawScope.() -> Unit) = drawIntoCanvas { canvas ->
        canvas.saveLayer(Rect(Offset(-s, -s), Size(s * 2, s * 2)), Paint().apply { this.alpha = opacity })
        draw()
        canvas.restore()
    }
    translate(tip.x, tip.y) {
        scale(scale, scale, pivot = Offset.Zero) {
            rotate(-18f, pivot = Offset.Zero) {
                layer(0.18f * alpha) { pieces.forEach { it.draw(this, Color.Black, outline, Offset(s * 0.05f, s * 0.06f)) } }
                layer(alpha) {
                    pieces.forEach { it.draw(this, OUTLINE, outline) }
                    pieces.forEach { it.draw(this, it.fill, 0f) }
                    // Soft shade down the far side of the palm, the creases between the fingers, a shine on the finger.
                    drawRoundRect(GLOVE_SHADE, Offset(s * 0.19f, s * 0.56f), Size(s * 0.1f, s * 0.22f), CornerRadius(s * 0.05f))
                    val crease = s * 0.022f
                    drawLine(OUTLINE, Offset(s * 0.13f, s * 0.47f), Offset(s * 0.13f, s * 0.54f), crease, StrokeCap.Round)
                    drawLine(OUTLINE, Offset(s * 0.22f, s * 0.52f), Offset(s * 0.22f, s * 0.58f), crease, StrokeCap.Round)
                    drawRoundRect(Color.White, Offset(-s * 0.05f, s * 0.06f), Size(s * 0.035f, s * 0.2f), CornerRadius(s * 0.02f))
                    drawRoundRect(GLOVE_SHADE, Offset(s * 0.02f, s * 0.08f), Size(s * 0.035f, s * 0.36f), CornerRadius(s * 0.02f))
                }
            }
        }
    }
}

/** One rounded piece of the glove, in glove units: drawn grown by an outline, or as its fill. */
private class GlovePiece(val rect: Rect, val radius: Float, val fill: Color, val turn: Float = 0f, val pivot: Offset = rect.center) {
    fun draw(scope: DrawScope, color: Color, grow: Float, shift: Offset = Offset.Zero) = with(scope) {
        rotate(turn, pivot = pivot + shift) {
            drawRoundRect(
                color,
                rect.topLeft + shift - Offset(grow, grow),
                Size(rect.width + grow * 2, rect.height + grow * 2),
                CornerRadius(radius + grow),
            )
        }
    }
}

private fun gloveShapes(s: Float): List<GlovePiece> = listOf(
    // The cuff, then the palm with the three curled fingers on top, the thumb and the pointing finger.
    GlovePiece(Rect(-s * 0.16f, s * 0.76f, s * 0.34f, s * 0.94f), s * 0.07f, CUFF),
    GlovePiece(Rect(-s * 0.13f, s * 0.38f, s * 0.31f, s * 0.82f), s * 0.15f, GLOVE),
    GlovePiece(Rect(s * 0.04f, s * 0.36f, s * 0.17f, s * 0.54f), s * 0.065f, GLOVE),
    GlovePiece(Rect(s * 0.13f, s * 0.4f, s * 0.26f, s * 0.58f), s * 0.065f, GLOVE),
    GlovePiece(Rect(s * 0.21f, s * 0.46f, s * 0.33f, s * 0.62f), s * 0.06f, GLOVE),
    GlovePiece(Rect(-s * 0.27f, s * 0.48f, s * 0.0f, s * 0.62f), s * 0.07f, GLOVE, turn = -35f, pivot = Offset(-s * 0.02f, s * 0.6f)),
    GlovePiece(Rect(-s * 0.085f, 0f, s * 0.085f, s * 0.52f), s * 0.085f, GLOVE),
)
